import{_ as e,o as a,c as i,a5 as n}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"UC — View AI Credit Tracking","description":"","frontmatter":{},"headers":[],"relativePath":"feature/subscription-billing/3-9-5-view-ai-credit-tracking/spec.md","filePath":"feature/subscription-billing/3-9-5-view-ai-credit-tracking/spec.md"}'),r={name:"feature/subscription-billing/3-9-5-view-ai-credit-tracking/spec.md"};function o(c,t,h,d,s,l){return a(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="uc-—-view-ai-credit-tracking" tabindex="-1">UC — View AI Credit Tracking <a class="header-anchor" href="#uc-—-view-ai-credit-tracking" aria-label="Permalink to &quot;UC — View AI Credit Tracking&quot;">​</a></h1><p>&gt; <strong>BA hiện hành 2026-10-19:</strong> mở rộng Creator thành Manager/Creator/Owner, theo từng thành viên và kỳ subscription, không phải tháng dương lịch. Owner xem toàn Agency; thành viên xem mình. Owner không có trần cá nhân. Xem <a href="./../member-credit/spec.html">member-credit/spec.md</a> cho quyết định mới và trạng thái thực thi; API tracking tổng hợp bên dưới là thiết kế lịch sử, chưa được triển khai bởi configuration foundation.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.9.5</td></tr><tr><td>Feature</td><td>View AI Credit Tracking</td></tr><tr><td>Domain</td><td>Subscription (FR 3.9)</td></tr><tr><td>Role</td><td>CREATOR, OWNER</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>Draft — BA confirmed, chưa code</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Giám sát lượng credit Creator đã dùng cho tính năng AI trong tháng (tạo ảnh, content, video).</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một Creator hoặc Owner, tôi muốn xem credit AI đã dùng trong tháng, để kiểm soát chi phí sử dụng AI.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li>Creator xem credit CHÍNH MÌNH đã dùng.</li><li>Owner xem tổng hợp credit toàn Agency, breakdown theo từng Creator.</li><li>Breakdown theo loại tính năng: tạo ảnh, tạo content, tạo video (map với FR 3.7.2, 3.7.5, 3.7.7).</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Trang <code>/settings/ai-credit</code> (Creator xem của mình), <code>/agencies/:id/ai-credit</code> (Owner xem toàn Agency).</li></ul><h2 id="_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" tabindex="-1">5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật) <a class="header-anchor" href="#_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/ai-credit/me?month=2026-09</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { &quot;used&quot;, &quot;limit&quot;, &quot;byFeature&quot;: {...} } }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET /api/v1/agencies/{id}/ai-credit?month=2026-09</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: [{ &quot;creatorId&quot;, &quot;used&quot;, &quot;limit&quot; }] }</span></span></code></pre></div><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>Không có quyền xem credit của Creator khác (chỉ Owner mới xem toàn Agency) → 403 <code>FORBIDDEN</code>.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>Tháng mới bắt đầu, credit reset — cần xác nhận cơ chế reset hàng tháng hay cộng dồn khi thiết kế kỹ thuật (<a href="./../../../BA/11-data-entities-glossary.html">11-data-entities-glossary.md</a> câu hỏi mở AICreditLedger).</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Hiển thị đúng credit đã dùng, breakdown theo feature.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Không có.</li></ul><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../BA/08-subscription-billing.html">08-subscription-billing.md</a></p>`,23)])])}const g=e(r,[["render",o]]);export{p as __pageData,g as default};
